#!/usr/bin/env node
/**
 * Publish the PUBLIC subset of the canonical Help docs to the Docusaurus site.
 *
 * Single source of truth = `qms-app/content/help/**`. This copies only the files
 * flagged `access: public` in frontmatter into the marketing repo's
 * `marketing/docs/docs/**` (stripping the `access` key; all other Docusaurus
 * frontmatter and the original Markdown — including its relative links — are kept
 * as-is). The required `_category_.json` files for those docs' folders are copied
 * too so the autogenerated sidebar renders.
 *
 * Flags:
 *   --dry-run   print what would change; write nothing
 *   --prune     also DELETE non-public *.md/*.mdx already in the target so the
 *               public site shows ONLY the curated subset (off by default — the
 *               target is a separate git repo; deletions are opt-in)
 *
 * Assumes the marketing repo is a sibling of qms-app (…/QMS/qms-app, …/QMS/marketing).
 * Override the target with HELP_PUBLIC_TARGET=/abs/path/to/marketing/docs/docs.
 */
import {
  readFileSync,
  writeFileSync,
  mkdirSync,
  rmSync,
  readdirSync,
  statSync,
  existsSync,
  copyFileSync,
} from 'node:fs'
import { join, relative, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import matter from 'gray-matter'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const SRC = join(ROOT, 'content', 'help')
const TARGET = process.env.HELP_PUBLIC_TARGET || join(ROOT, '..', 'marketing', 'docs', 'docs')

const DRY = process.argv.includes('--dry-run')
const PRUNE = process.argv.includes('--prune')

function walk(dir, pred) {
  const out = []
  for (const name of readdirSync(dir)) {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) out.push(...walk(full, pred))
    else if (pred(name)) out.push(full)
  }
  return out
}

if (!existsSync(SRC)) {
  console.error(`[publish] source not found: ${SRC}`)
  process.exit(1)
}
if (!existsSync(TARGET)) {
  console.error(
    `[publish] target docs dir not found: ${TARGET}\n` +
      `Set HELP_PUBLIC_TARGET to the Docusaurus docs/ path, or run where the marketing repo is a sibling.`,
  )
  process.exit(1)
}

const mdFiles = walk(SRC, (n) => n.endsWith('.md') || n.endsWith('.mdx'))
const publicRel = new Set()
const neededDirs = new Set()
let written = 0

for (const file of mdFiles) {
  const { data, content } = matter(readFileSync(file, 'utf8'))
  if (data.access !== 'public') continue
  const rel = relative(SRC, file).replace(/\\/g, '/')
  publicRel.add(rel)
  // strip the access key; keep everything else (id, title, sidebar_position, …)
  const { access: _drop, ...rest } = data
  const out = matter.stringify(content, rest)
  const dest = join(TARGET, rel)
  // collect this doc's folder + ancestors so we can carry their _category_.json
  let d = dirname(rel)
  while (d && d !== '.') {
    neededDirs.add(d)
    d = dirname(d)
  }
  console.log(`${DRY ? '[dry] ' : ''}publish  ${rel}`)
  if (!DRY) {
    mkdirSync(dirname(dest), { recursive: true })
    writeFileSync(dest, out)
  }
  written++
}

// Carry _category_.json for folders that contain published docs.
for (const d of neededDirs) {
  const catSrc = join(SRC, d, '_category_.json')
  if (!existsSync(catSrc)) continue
  const catDest = join(TARGET, d, '_category_.json')
  console.log(`${DRY ? '[dry] ' : ''}category ${d}/_category_.json`)
  if (!DRY) {
    mkdirSync(dirname(catDest), { recursive: true })
    copyFileSync(catSrc, catDest)
  }
}

// Non-public docs currently in the target → report (or prune with --prune).
const targetMd = walk(TARGET, (n) => n.endsWith('.md') || n.endsWith('.mdx'))
const stale = targetMd.filter((f) => !publicRel.has(relative(TARGET, f).replace(/\\/g, '/')))
if (stale.length) {
  console.log(`\n${PRUNE ? 'Pruning' : 'Non-public present (kept; pass --prune to remove)'}:`)
  for (const f of stale) {
    const rel = relative(TARGET, f).replace(/\\/g, '/')
    console.log(`  ${PRUNE ? (DRY ? '[dry] delete' : 'deleted') : '-'} ${rel}`)
    if (PRUNE && !DRY) rmSync(f)
  }
}

console.log(
  `\n[publish] ${DRY ? '(dry-run) ' : ''}${written} public doc(s) -> ${relative(ROOT, TARGET)}`,
)
